// SetPropertyTimeout sets the "timeout" property.
func (x *Resolver) SetPropertyTimeout(value uint32) {
	var v gobject.Value
	v.Init(gobject.TypeUlongVal)
	v.SetUlong(value)
	x.SetProperty("timeout", &v)
}

// GetPropertyTimeout gets the "timeout" property.
func (x *Resolver) GetPropertyTimeout() uint32 {
	var v gobject.Value
	x.GetProperty("timeout", &v)
	return v.GetUlong()
}

func (x *Resolver) ConnectReload(cb *func(Resolver)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "reload", cbRefPtr)
	}

	fcb := func(clsPtr uintptr) {
		fa := Resolver{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa)
	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "reload", cbRefPtr)
}

